tition by sku order by 1) rw from pomme_db.maplemonk.woo_commerce_amiko_products, lateral flatten (input => attributes ) A where A.value like \'%size%\' ) where rw = 1 ) j on a.sku = j.sku left join (select sku, model from (select sku , replace(A.value:value,\'\"\',\'\') model , row_number() over (partition by sku order by 1) rw from pomme_db.maplemonk.woo_commerce_amiko_product_variations, lateral flatten (input => meta_data ) A where A.value like \'%iconic_cffv_19613_model%\' ) where rw = 1 union all select sku, color_specific from (select sku , replace(A.value:value,\'\"\',\'\') color_specific , row_number() over (partition by sku order by 1) rw from pomme_db.maplemonk.woo_commerce_amiko_products, lateral flatten (input => meta_data ) A where A.value like \'%iconic_cffv_19613_model%\' ) where rw = 1 ) k on a.sku = k.sku left join (select sku, type from (select sku , replace(A.value:value,\'\"\',\'\') type , row_number() over (partition by sku order by 1) rw from pomme_db.maplemonk.woo_commerce_amiko_product_variations, lateral flatten (input => meta_data ) A where A.value like \'%iconic_cffv_19613_type%\' ) where rw = 1 union all select sku, color_specific from (select sku , replace(A.value:value,\'\"\',\'\') color_specific , row_number() over (partition by sku order by 1) rw from pomme_db.maplemonk.woo_commerce_amiko_products, lateral flatten (input => meta_data ) A where A.value like \'%iconic_cffv_19613_type%\' ) where rw = 1 ) l on a.sku = l.sku left join (select distinct id, sku, name, replace(A.value:name,\'\"\',\'\') product_short_name , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => tags) A where index = 0) m on a.parent_id = m.id left join (select distinct id, sku, name, replace(A.value:name,\'\"\',\'\') product_short_name , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => tags) A where index = 1) n on a.parent_id = n.id left join ( select a.id, a.sku, a.name, b.categ