REPLACE TABLE pomme_db.MAPLEMONK.Woocommerce_All_customers_amiko AS select _AIRBYTE_UNIQUE_KEY, ID, ROLE, EMAIL, _LINKS, BILLING, SHIPPING, \'www.amikoandfriends.com\' as shop_url, USERNAME, LAST_NAME, META_DATA, AVATAR_URL, FIRST_NAME, DATE_CREATED, DATE_MODIFIED, DATE_CREATED_GMT, DATE_MODIFIED_GMT, IS_PAYING_CUSTOMER, _AIRBYTE_AB_ID, _AIRBYTE_EMITTED_AT, _AIRBYTE_NORMALIZED_AT, _AIRBYTE_WOOCOMMERCE_amiko_CUSTOMERS_HASHID, \'Woocommerce_Amiko\' AS Shop_Name from pomme_db.MAPLEMONK.WOOCOMMERCE_Amiko_CUSTOMERS ; CREATE OR REPLACE TABLE pomme_db.MAPLEMONK.Woocommerce_All_orders_amiko AS select _AIRBYTE_UNIQUE_KEY, ID, TOTAL, _LINKS, NUMBER, STATUS, BILLING, REFUNDS, VERSION, CART_TAX, CURRENCY, SET_PAID, SHIPPING, \'www.amikoandfriends.com\' as shop_url, CART_HASH, DATE_PAID, FEE_LINES, META_DATA, ORDER_KEY, PARENT_ID, TAX_LINES, TOTAL_TAX, LINE_ITEMS, CREATED_VIA, CUSTOMER_ID, COUPON_LINES, DATE_CREATED, DISCOUNT_TAX, SHIPPING_TAX, CUSTOMER_NOTE, DATE_MODIFIED, DATE_PAID_GMT, DATE_COMPLETED, DISCOUNT_TOTAL, PAYMENT_METHOD, SHIPPING_LINES, SHIPPING_TOTAL, TRANSACTION_ID, DATE_CREATED_GMT, DATE_MODIFIED_GMT, DATE_COMPLETED_GMT, PRICES_INCLUDE_TAX, CUSTOMER_IP_ADDRESS, CUSTOMER_USER_AGENT, PAYMENT_METHOD_TITLE, _AIRBYTE_AB_ID, _AIRBYTE_EMITTED_AT, _AIRBYTE_NORMALIZED_AT, _AIRBYTE_WOOCOMMERCE_amiko_ORDERS_HASHID, \'Woocommerce_Amiko\' AS Shop_Name from pomme_db.maplemonk.woocommerce_amiko_orders ; create or replace table pomme_db.maplemonk.woocommerce_all_orders_products_attributes_amiko as select ordeR_id, LINE_ITEM_ID, product_id, z.sku, grip, Z.product_short_name1, z.product_short_name2, z.category1, z.category2, z.category3, z.category4, z.category5, shop_name, pa.color_general, pa.size, pa.gender, pa.product_brand, pa.color_specific, pa.attribute_1, pa.attribute_2, pa.attribute_3, pa.supplier, pa.model, pa.type from (select a.id order_id, a.LINE_ITEM_ID, a.product_id, a.sku, b.grip, ifnull(c.product_short_name,\'NA\') product_short_name1, ifnull(d.product_short_name,\'NA\') product_short_name2, ifnull(e.category,\'NA\') category1, ifnull(f.category,\'NA\') category2, ifnull(g.category,\'NA\') category3, ifnull(h.category,\'NA\') category4, ifnull(i.category,\'NA\') category5, a.shop_name from ( select distinct id, A.VALUE:product_id::STRING product_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, shop_name from pomme_db.MAPLEMONK.Woocommerce_All_orders_amiko, LATERAL FLATTEN (INPUT => LINE_ITEMS)A , lateral flatten (input => A.value:meta_data) B ) a left join (select distinct id, A.VALUE:product_id::STRING product_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, case when lower(B.value:display_key) = \'grip\' then replace(B.value:display_value,\'\"\',\'\') end as Grip, shop_name from pomme_db.MAPLEMONK.Woocommerce_All_orders_amiko, LATERAL FLATTEN (INPUT => LINE_ITEMS)A , lateral flatten (input => A.value:meta_data) B where Grip is not null) b on a.shop_name = b.shop_name and a.id = b.id and a.line_item_id = b.line_item_id left join (select id, sku, name, replace(A.value:name,\'\"\',\'\') product_short_name , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => tags) A where index = 0) c on a.shop_name = c.shop_name and a.product_id = c.id left join (select id, sku, name, replace(A.value:name,\'\"\',\'\') product_short_name , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => tags) A where index = 1) d on a.shop_name = d.shop_name and a.product_id = d.id left join (select id, sku, name, replace(A.value:name,\'\"\',\'\') Category , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => categories) A where index = 0) e on a.shop_name = e.shop_name and a.product_id = e.id left join (select id, sku, name, replace(A.value:name,\'\"\',\'\') Category , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => categories) A where index = 1) f on a.shop_name = f.shop_name and a.product_id = f.id left join (select id, sku, name, replace(A.value:name,\'\"\',\'\') Category , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => categories) A where index = 2) g on a.shop_name = g.shop_name and a.product_id = g.id left join (select id, sku, name, replace(A.value:name,\'\"\',\'\') Category , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => categories) A where index = 3) h on a.shop_name = h.shop_name and a.product_id = h.id left join (select id, sku, name, replace(A.value:name,\'\"\',\'\') Category , shop_name from pomme_db.MAPLEMONK.Woocommerce_All_products_amiko, lateral flatten (input => categories) A where index = 4) i on a.shop_name = i.shop_name and a.product_id = i.id ) z left join pomme_db.maplemonk.product_attributes_amiko pa on z.sku = pa.sku ; CREATE OR REPLACE TABLE pomme_DB.maplemonk.woocommerce_All_orders_items_discount_amiko AS SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, discount_total/count(distinct A.value:id) over (partition by id, shop_name) AS discount_allocations, shop_name FROM pomme_DB.maplemonk.WOOCOMMERCE_ALL_ORDERS_amiko, LATERAL FLATTEN (INPUT => LINE_ITEMS)A ; CREATE OR REPLACE TABLE pomme_DB.maplemonk.woocommerce_All_orders_items_tax_amiko AS SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, shop_name, replace(A.VALUE:total_tax,\'\"\',\'\') AS tax_lines FROM pomme_DB.maplemonk.WOOCOMMERCE_ALL_ORDERS_amiko, LATERAL FLATTEN (INPUT => LINE_ITEMS)A ; CREATE OR REPLACE TABLE pomme_db.maplemonk.WOOCOMMERCE_All_Refunds_amiko AS select null id, null SKU, null product_id, null refund_amount, null quantity, \'Woocommerce_Amiko\' AS Shop_Name ; CREATE OR REPLACE TABLE pomme_DB.maplemonk.Woocommerce_All_orders_items_amiko AS WITH CTE AS (SELECT SHOP_NAME, ID::VARCHAR(16777216) AS ORDER_ID, order_key AS ORDER_NAME, CUSTOMER_id, concat(replace(billing:first_name,\'\"\',\'\'),\' \',replace(billing:last_name,\'\"\',\'\')) NAME, replace(billing:phone,\'\"\',\'\') PHONE, replace(billing:email,\'\"\',\'\') EMAIL, replace(shipping:country,\'\"\',\'\') Country, replace(shipping:state,\'\"\',\'\') State, replace(shipping:city,\'\"\',\'\') City, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, A.VALUE:product_id::STRING AS PRODUCT_ID, A.VALUE:name::STRING AS PRODUCT_NAME, A.VALUE:parent_name::STRING AS PRODUCT_PARENT_NAME, CURRENCY, status order_status, replace(refunds:id,\'\"\',\'\') refunds_id, DATE_CREATED_GMT::DATETIME AS order_timestamp, replace(A.VALUE:total,\'\"\',\'\') + replace(A.VALUE:total_tax,\'\"\',\'\') AS LINE_ITEM_SALES, shipping_total/ COUNT(A.VALUE:id) OVER(PARTITION BY ORDER_ID ) AS SHIPPING_PRICE, shipping_tax/ COUNT(A.VALUE:id) OVER(PARTITION BY ORDER_ID ) as shipping_tax, replace(A.VALUE:quantity,\'\"\',\'\')::FLOAT as QUANTITY, \'WooCommerce\' AS Source, payment_method FROM pomme_DB.maplemonk.woocommerce_All_orders_amiko, LATERAL FLATTEN (INPUT => LINE_ITEMS)A) SELECT CTE.*, pa.grip grip, pa.size size, pa.color_general color_general, pa.color_specific, pa.product_brand, pa.gender, pa.attribute_1, pa.attribute_2, pa.attribute_3, pa.supplier, pa.model, pa.type, pa.product_short_name1, pa.product_short_name2, pa.category1, pa.category2, pa.category3, pa.category4, pa.category5, IFNULL(D.DISCOUNT_ALLOCATIONS,0) AS DISCOUNT, CTE.LINE_ITEM_SALES AS GROSS_SALES_AFTER_TAX, CTE.LINE_ITEM_SALES - ifnull(tax_lines,0) AS GROSS_SALES_BEFORE_TAX, CTE.LINE_ITEM_SALES - ifnull(tax_lines,0) - ifnull(discount_allocations,0) AS NET_SALES_BEFORE_TAX, IFNULL(T.TAX_lines,0) AS TAX, CTE.LINE_ITEM_SALES + ifnull(shipping_price,0) + ifnull(shipping_tax,0) + ifnull(refund_amount,0) AS TOTAL_SALES, refund_amount as refund_amount, R.quantity as refunded_quantity FROM CTE LEFT JOIN pomme_db.maplemonk.woocommerce_All_orders_items_tax_amiko T ON CTE.ORDER_ID = T.ORDER_ID AND CTE.LINE_ITEM_ID = T.LINE_ITEM_ID and CTE.shop_name = T.shop_name LEFT JOIN pomme_db.maplemonk.woocommerce_All_orders_items_discount_amiko D ON CTE.ORDER_ID = D.ORDER_ID AND CTE.LINE_ITEM_ID = D.LINE_ITEM_ID and CTE.shop_name = D.shop_name LEFT JOIN pomme_db.maplemonk.woocommerce_All_Refunds_amiko R ON CTE.refunds_ID = R.ID AND CTE.product_id = R.product_id and CTE.shop_name = R.shop_name left join ( select * from pomme_db.maplemonk.woocommerce_all_orders_products_attributes_amiko qualify row_number() over (partition by order_id,product_id,shop_name,sku,line_item_id order by 1 desc) = 1 ) pa on CTE.order_id = pa.order_id and CTE.product_id = pa.product_id and CTE.shop_name = pa.shop_name and CTE.sku = pa.sku and CTE.line_item_id = pa.line_item_id ; CREATE OR REPLACE TABLE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko AS WITH exchange_rate as ( Select to_Date(\"DATE \") as date, EUR_SEK, USD_SEK, DKK_SEK from pomme_db.maplemonk.exhange_rates where date < \'2025-04-21\' or date > \'2025-07-23\' Union all select date, parse_json(rates):SEK::float as EUR_SEK, div0(parse_json(rates):SEK,parse_json(rates):USD)::float as USD_SEK, div0(parse_json(rates):SEK,parse_json(rates):DKK)::float as DKK_SEK, from pomme_db.maplemonk.pomme_exchange_Rates where date >= \'2025-04-21\' or date < \'2025-07-24\' ), date_range AS ( SELECT CURRENT_DATE AS date_value UNION ALL SELECT date_value - 1 FROM date_range WHERE date_value - 1 >= (SELECT MIN(date) FROM exchange_rate) ), AVG_EXCHANGE_RATES AS( SELECT d.date_value, AVG(e.DKK_SEK), AVG(e.USD_SEK), AVG(e.EUR_SEK), div0(sum(e.DKK_SEK),SUM(CASE WHEN e.DKK_SEK IS NULL THEN 0 ELSE 1 END)) AS AVG_DKK_SEK, div0(sum(e.USD_SEK),SUM(CASE WHEN e.USD_SEK IS NULL THEN 0 ELSE 1 END)) AS AVG_USD_SEK, div0(sum(e.EUR_SEK),SUM(CASE WHEN e.EUR_SEK IS NULL THEN 0 ELSE 1 END)) AS AVG_EUR_SEK FROM date_range d LEFT JOIN exchange_rate e ON e.date BETWEEN d.date_value - 6 AND d.date_value GROUP BY d.date_value ORDER BY d.date_value desc ) SELECT O.SHOP_NAME, O.ORDER_ID, O.ORDER_NAME, O.CUSTOMER_id customer_id, O.Name, O.EMAIL, O.PHONE, O.LINE_ITEM_ID, O.SKU, O.PRODUCT_ID, o.product_name, O.CURRENCY, o.city, o.State, o.country, o.grip, o.product_brand, o.size, o.color_general, o.color_specific, o.attribute_1, o.attribute_2, o.attribute_3, o.model, o.type, o.supplier, o.gender, o.product_short_name1, o.product_short_name2, case when lower(o.product_name) like \'%bling%\' then \'Bling\' when lower(o.product_name) like \'%classic%\' then \'Classic\' end as Print, o.category1, o.category2, o.category3, o.category4, o.category5, O.order_status, O.order_timestamp, case when o.currency = \'DKK\' then O.LINE_ITEM_SALES*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.LINE_ITEM_SALES*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.LINE_ITEM_SALES*IFNULL(USD_SEK,AVG_USD_SEK) else O.line_item_sales end as line_item_sales, case when o.currency = \'DKK\' then O.SHIPPING_PRICE*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.SHIPPING_PRICE*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.SHIPPING_PRICE*IFNULL(USD_SEK,AVG_USD_SEK) else O.SHIPPING_PRICE end as SHIPPING_PRICE, O.QUANTITY, o.refunded_quantity, case when o.currency = \'DKK\' then O.refund_amount*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.refund_amount*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.refund_amount*IFNULL(USD_SEK,AVG_USD_SEK) else O.refund_amount end as refund_amount, case when o.currency = \'DKK\' then O.TAX*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.TAX*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.TAX*IFNULL(USD_SEK,AVG_USD_SEK) else O.TAX end as TAX, case when o.currency = \'DKK\' then O.DISCOUNT*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.DISCOUNT*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.DISCOUNT*IFNULL(USD_SEK,AVG_USD_SEK) else O.DISCOUNT end as DISCOUNT, case when o.currency = \'DKK\' then O.GROSS_SALES_AFTER_TAX*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.GROSS_SALES_AFTER_TAX*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.GROSS_SALES_AFTER_TAX*IFNULL(USD_SEK,AVG_USD_SEK) else O.GROSS_SALES_AFTER_TAX end as GROSS_SALES_AFTER_TAX, case when o.currency = \'DKK\' then O.GROSS_SALES_BEFORE_TAX*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.GROSS_SALES_BEFORE_TAX*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.GROSS_SALES_BEFORE_TAX*IFNULL(USD_SEK,AVG_USD_SEK) else O.GROSS_SALES_BEFORE_TAX end as GROSS_SALES_BEFORE_TAX, case when o.currency = \'DKK\' then O.NET_SALES_BEFORE_TAX*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.NET_SALES_BEFORE_TAX*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.NET_SALES_BEFORE_TAX*IFNULL(USD_SEK,AVG_USD_SEK) else O.NET_SALES_BEFORE_TAX end as NET_SALES_BEFORE_TAX, case when o.currency = \'DKK\' then O.TOTAL_SALES*IFNULL(DKK_SEK,AVG_DKK_SEK) when o.currency = \'EUR\' then O.TOTAL_SALES*IFNULL(EUR_SEK,AVG_EUR_SEK) when o.currency = \'USD\' then O.TOTAL_SALES*IFNULL(USD_SEK,AVG_USD_SEK) else O.TOTAL_SALES end as TOTAL_SALES, payment_method FROM Pomme_db.maplemonk.woocommerce_All_orders_items_amiko O left join exchange_rate e on date = o.order_timestamp::date left join avg_exchange_rates av on O.order_timestamp::date = av.date_value ; ALTER TABLE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko ADD COLUMN new_customer_flag varchar(50); ALTER TABLE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko ADD COLUMN acquisition_product varchar(16777216); UPDATE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id, order_timestamp, CASE WHEN order_timestamp <> Min(order_timestamp) OVER ( partition BY customer_id) THEN \'Repeat\' ELSE \'New\' END AS Flag FROM pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko)AS B WHERE A.order_id = B.order_id AND A.customer_id = B.customer_id; UPDATE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko SET new_customer_flag = CASE WHEN new_customer_flag IS NULL THEN \'New\' ELSE new_customer_flag END; UPDATE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id, order_timestamp, CASE WHEN Last_day(order_timestamp, \'month\') <> Last_day(Min(order_timestamp) OVER ( partition BY customer_id)) THEN \'Repeated\' ELSE \'New\' END AS Flag FROM pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko)AS B WHERE A.order_id = B.order_id AND A.customer_id = B.customer_id; CREATE OR replace temporary TABLE pomme_DB.maplemonk.temp_product_amiko AS SELECT DISTINCT customer_id, product_name, Row_number() OVER (partition BY customer_id ORDER BY LINE_ITEM_SALES DESC) rowid FROM ( SELECT DISTINCT customer_id, order_timestamp, product_name, LINE_ITEM_SALES , Min(order_timestamp) OVER (partition BY customer_id) firstOrderdate FROM pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko )res WHERE order_timestamp=firstorderdate; UPDATE pomme_DB.maplemonk.FACT_ITEMS_woocommerce_amiko AS A SET A.acquisition_product=B.product_name FROM ( SELECT * FROM pomme_DB.maplemonk.temp_product_amiko WHERE rowid=1)B WHERE A.customer_id = B.customer_id;",
                    "transaction": true
                }
            ) }}
